# ADDED: PATCH /chats/message - atomic message update
@router.patch("/chats/message")
async def api_update_message(request: Request):
    """
    Update fields of a single message (atomic, merge-safe).

    Payload: { "chat_id": "...", "doc_id": "...", "update": { ...fields } }
    """
    from codx.junior.db import Message
    data = await request.json()
    codx_junior_session = request.state.codx_junior_session
    chat_manager = codx_junior_session.get_chat_manager()

    chat_id = data.get("chat_id")
    doc_id = data.get("doc_id")
    update = data.get("update", {})

    if not chat_id or not doc_id:
        return {"error": "missing chat_id or doc_id"}

    chat = chat_manager.find_by_id(chat_id=chat_id)
    if not chat:
        return {"error": f"chat '{chat_id}' not found"}

    msg = next((m for m in chat.messages if m.doc_id == doc_id), None)
    if not msg:
        return {"error": f"message '{doc_id}' not found"}

    for key, value in update.items():
        setattr(msg, key, value)

    chat_manager.save_chat(chat)
    return {"ok": True}


# ADDED: DELETE /chats/message - remove single message
@router.delete("/chats/message")
async def api_delete_message(request: Request):
    """
    Remove a single message from a chat.

    Payload: { "chat_id": "...", "doc_id": "..." }
    """
    data = await request.json()
    codx_junior_session = request.state.codx_junior_session
    chat_manager = codx_junior_session.get_chat_manager()

    chat_id = data.get("chat_id")
    doc_id = data.get("doc_id")

    if not chat_id or not doc_id:
        return {"error": "missing chat_id or doc_id"}

    chat = chat_manager.find_by_id(chat_id=chat_id)
    if not chat:
        return {"error": f"chat '{chat_id}' not found"}

    original_len = len(chat.messages)
    chat.messages = [m for m in chat.messages if m.doc_id != doc_id]

    if len(chat.messages) == original_len:
        return {"error": f"message '{doc_id}' not found"}

    chat_manager.save_chat(chat)
    return {"ok": True}


